CREATE OR REPLACE FUNCTION public.set_staff_role(p_user uuid,p_role public.app_role,p_collector uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin required'; END IF; IF p_role IS NULL THEN RAISE EXCEPTION 'Role required'; END IF; IF p_user=auth.uid() AND p_role<>'admin' THEN RAISE EXCEPTION 'Cannot remove your own admin access'; END IF; IF p_role='collector' AND p_collector IS NULL THEN RAISE EXCEPTION 'Assign a collector'; END IF; INSERT INTO public.user_roles(user_id,role,collector_id) VALUES(p_user,p_role,CASE WHEN p_role='admin' THEN NULL ELSE p_collector END) ON CONFLICT(user_id) DO UPDATE SET role=excluded.role,collector_id=excluded.collector_id; END $$;
REVOKE ALL ON FUNCTION public.set_staff_role(uuid,public.app_role,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.set_staff_role(uuid,public.app_role,uuid) TO authenticated;